import React from 'react';
import { Clinic } from '../types/clinic';

interface Props {
    clinic: Clinic;
}

const ClinicRow: React.FC<Props> = ({ clinic }) => {
    const instaLabel = clinic.instagram
        ? clinic.instagram.replace(/^https?:\/\/(www\.)?instagram\.com\/?/, '').replace(/\/$/, '')
        : null;

    return (
        <tr>
            <td>{clinic.name}</td>
            <td>{clinic.address}</td>
            <td>
                {clinic.instagram ? (
                    <a href={clinic.instagram} target="_blank" rel="noopener noreferrer">
                        @{instaLabel}
                    </a>
                ) : (
                    '—'
                )}
            </td>
        </tr>
    );
};

export default ClinicRow;
